1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResults {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE = 0.1;
57	const BASE_PREMIUMS: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	// Intermediate amounts are kept as fractions; only the final figure is rounded.
67	// Binary floating point makes sums like 100 * 1.1 + 5 land on 115.00000000000001,
68	// so that noise is trimmed before rounding.
69	const withoutFloatingPointNoise = (amount: number): number =>
70	  Number(amount.toPrecision(12));
71	
72	// Rounding always favours MHPCO, which means up for what the customer pays.
73	const roundPremiumInMHPCOsFavor = (amount: number): number =>
74	  Math.ceil(withoutFloatingPointNoise(amount));
75	
76	// Three alike components form a building block priced as a unit.
77	// "Alike" means the same item type, so each group below is one candidate block
78	// and a list may contain several blocks.
79	const BLOCK_SIZE = 3;
80	const BLOCK_BASE_PREMIUM = 60;
81	
82	const alikeGroupsOf = (items: Item[]): Item[][] => {
83	  const groups = new Map<string, Item[]>();
84	  for (const item of items) {
85	    const alike = groups.get(item.type);
86	    if (alike) alike.push(item);
87	    else groups.set(item.type, [item]);
88	  }
89	  return [...groups.values()];
90	};
91	
92	const formsABlock = (group: Item[]): boolean => group.length === BLOCK_SIZE;
93	
94	// MHPCO insures only what its price list names. Every per-type figure is read
95	// through here, so a type the price list does not name can never reach a
96	// calculation as a missing number.
97	const priceListEntry = (
98	  priceList: Record<string, number>,
99	  item: Item,
100	): number => {
101	  const price = priceList[item.type];
102	  if (price === undefined) {
103	    throw new Error(`Not on the MHPCO price list: ${item.type}`);
104	  }
105	  return price;
106	};
107	
108	const basePremiumOfItem = (item: Item): number =>
109	  priceListEntry(BASE_PREMIUMS, item);
110	
111	const sumOfIndividualBasePremiums = (items: Item[]): number =>
112	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
113	
114	const basePremiumOfGroup = (group: Item[]): number =>
115	  formsABlock(group) ? BLOCK_BASE_PREMIUM : sumOfIndividualBasePremiums(group);
116	
117	const basePremiumOf = (items: Item[]): number =>
118	  alikeGroupsOf(items).reduce(
119	    (sum, group) => sum + basePremiumOfGroup(group),
120	    0,
121	  );
122	
123	const CURSE_SURCHARGE = 0.5;
124	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
125	const HIGH_ENCHANTMENT_LEVEL = 5;
126	
127	// Every surcharge an item can attract, each applying independently of the rest.
128	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
129	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
130	  {
131	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
132	    rate: HIGH_ENCHANTMENT_SURCHARGE,
133	  },
134	];
135	
136	// Item-specific surcharges are charged on the affected item's own base premium,
137	// not on the policy total.
138	const itemSurchargeRateOf = (item: Item): number =>
139	  ITEM_SURCHARGES.reduce(
140	    (total, { applies, rate }) => (applies(item) ? total + rate : total),
141	    0,
142	  );
143	
144	const itemSurchargesOf = (items: Item[]): number =>
145	  items.reduce(
146	    (sum, item) => sum + basePremiumOfItem(item) * itemSurchargeRateOf(item),
147	    0,
148	  );
149	
150	const LOYALTY_DISCOUNT = -0.2;
151	const LOYALTY_YEARS = 2;
152	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
153	
154	// What a policy-wide modifier may look at: the customer, and how many contracts
155	// this customer already holds in the scenario.
156	interface PolicyContext {
157	  customer: Customer;
158	  previousContracts: number;
159	}
160	
161	// Every policy-wide modifier, each charged on the policy base premium and each
162	// applying independently of the rest. Surcharges carry a positive rate,
163	// discounts a negative one, so all of them combine by plain addition.
164	const POLICY_MODIFIERS: {
165	  applies: (context: PolicyContext) => boolean;
166	  rate: number;
167	}[] = [
168	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE },
169	  {
170	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
171	    rate: LOYALTY_DISCOUNT,
172	  },
173	  {
174	    applies: ({ previousContracts }) => previousContracts > 0,
175	    rate: FOLLOW_UP_CONTRACT_DISCOUNT,
176	  },
177	];
178	
179	const policyModifiersOn = (
180	  policyBase: number,
181	  context: PolicyContext,
182	): number =>
183	  POLICY_MODIFIERS.reduce(
184	    (sum, { applies, rate }) =>
185	      applies(context) ? sum + policyBase * rate : sum,
186	    0,
187	  );
188	
189	const withProcessingFee = (amount: number): number => amount + PROCESSING_FEE;
190	
191	const INSURANCE_VALUES: Record<string, number> = {
192	  sword: 1000,
193	  amulet: 600,
194	  staff: 800,
195	  potion: 400,
196	  rune: 250,
197	  moonstone: 250,
198	};
199	
200	const DEDUCTIBLE = 100;
201	const CAP_MULTIPLE = 2;
202	
203	// A policy created by a quote step: the items it covers and how much of its
204	// payout cap is still available.
205	interface Policy {
206	  items: Item[];
207	  remainingCap: number;
208	}
209	
210	const insuranceSumOf = (items: Item[]): number =>
211	  items.reduce((sum, item) => sum + priceListEntry(INSURANCE_VALUES, item), 0);
212	
213	// Rounding always favours MHPCO, which means down for what MHPCO pays out.
214	const roundPayoutInMHPCOsFavor = (amount: number): number =>
215	  Math.floor(withoutFloatingPointNoise(amount));
216	
217	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
218	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
219	const FULL_REIMBURSEMENT_RATE = 1;
220	
221	// Every clause that can reimburse a damaged item at less than full value. A
222	// clause names the share of the damage amount it reimburses; where no clause
223	// applies the item is reimbursed in full.
224	const REIMBURSEMENT_CLAUSES: {
225	  applies: (item: Item) => boolean;
226	  rate: number;
227	}[] = [
228	  {
229	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL,
230	    rate: HIGH_ENCHANTMENT_REIMBURSEMENT_RATE,
231	  },
232	];
233	
234	const reimbursementRateFor = (item: Item): number =>
235	  REIMBURSEMENT_CLAUSES.find(({ applies }) => applies(item))?.rate ??
236	  FULL_REIMBURSEMENT_RATE;
237	
238	// A clause reduces the damage amount first; the deductible is withheld
239	// afterwards, once per damaged item.
240	const payoutForDamage = (damage: Damage, item: Item): number =>
241	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
242	
243	// A damage entry once matched to the covered item it was suffered by.
244	interface ResolvedDamage {
245	  damage: Damage;
246	  item: Item;
247	}
248	
249	// Every damage entry names a distinct covered item, so two entries of one type
250	// need two such items on the policy. A damage MHPCO cannot match to a covered
251	// item rejects the whole claim.
252	const resolveDamagesAgainst = (
253	  incident: Incident,
254	  policy: Policy,
255	): ResolvedDamage[] => {
256	  const unclaimed = [...policy.items];
257	  return incident.damages.map((damage) => {
258	    if (damage.amount < 0) {
259	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
260	    }
261	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
262	    if (index === -1) {
263	      throw new Error(`Not covered by this policy: ${damage.itemType}`);
264	    }
265	    return { damage, item: unclaimed.splice(index, 1)[0] };
266	  });
267	};
268	
269	// What the incident entitles the customer to, before the policy's remaining
270	// cap is allowed to reduce it.
271	const amountOwedForIncident = (incident: Incident, policy: Policy): number =>
272	  roundPayoutInMHPCOsFavor(
273	    resolveDamagesAgainst(incident, policy).reduce(
274	      (sum, { damage, item }) => sum + payoutForDamage(damage, item),
275	      0,
276	    ),
277	  );
278	
279	// Paying out draws the payout down from the policy's cap, so a claim both
280	// reports a figure and leaves the policy with less cover for later claims.
281	const drawFromCap = (policy: Policy, desired: number): ClaimResult => {
282	  const payout = Math.min(desired, policy.remainingCap);
283	  policy.remainingCap -= payout;
284	  return { payout, remainingCap: policy.remainingCap };
285	};
286	
287	const claimFor = (step: ClaimStep, policies: Policy[]): ClaimResult => {
288	  const policy = policies[step.policy];
289	  return drawFromCap(policy, amountOwedForIncident(step.incident, policy));
290	};
291	
292	// Item-specific modifiers are charged on the affected item's base premium;
293	// policy-wide modifiers are charged on the policy base premium (the sum of all
294	// item base premiums); the processing fee is added at the very end.
295	const premiumFor = (items: Item[], context: PolicyContext): number => {
296	  const policyBase = basePremiumOf(items);
297	  const modifiedPremium =
298	    policyBase +
299	    itemSurchargesOf(items) +
300	    policyModifiersOn(policyBase, context);
301	  return roundPremiumInMHPCOsFavor(withProcessingFee(modifiedPremium));
302	};
303	
304	const quoteFor = (step: QuoteStep, context: PolicyContext): QuoteResult => ({
305	  premium: premiumFor(step.items, context),
306	});
307	
308	const policyFor = (step: QuoteStep): Policy => ({
309	  items: step.items,
310	  remainingCap: CAP_MULTIPLE * insuranceSumOf(step.items),
311	});
312	
313	// A claim names its policy by the index of the step that created it, so
314	// policies are keyed by step index rather than pushed: claim steps simply leave
315	// no entry. Results are pushed in step order, so the two stay aligned.
316	export const runScenario = (scenario: Scenario): ScenarioResults => {
317	  const results: Result[] = [];
318	  const policies: Policy[] = [];
319	  let contractsIssued = 0;
320	  for (const [stepIndex, step] of scenario.steps.entries()) {
321	    if (step.op === "claim") {
322	      results.push(claimFor(step, policies));
323	      continue;
324	    }
325	    results.push(
326	      quoteFor(step, {
327	        customer: scenario.customer,
328	        previousContracts: contractsIssued,
329	      }),
330	    );
331	    policies[stepIndex] = policyFor(step);
332	    contractsIssued += 1;
333	  }
334	  return { results };
335	};
